
do

_G.FPS_TARGET = 120
_G.__FPS120_APPLIED__ = false

local function _ApplyFPS120()
    if _G.__FPS120_APPLIED__ then return true end
    local applied = false

    pcall(function()
        local GUS = nil
        if type(import) == "function" then
            GUS = import("GameUserSettings") or import("UGameUserSettings")
        end
        if GUS and GUS.GetGameUserSettings then
            local settings = GUS.GetGameUserSettings()
            if settings then
                if settings.SetFrameRateLimit then
                    settings:SetFrameRateLimit(120)
                    applied = true
                end
                if settings.SetVSyncEnabled then
                    settings:SetVSyncEnabled(false)
                end

            end
        end
    end)

    pcall(function()
        local candidates = {
            rawget(_G, "ConsoleCommand"),
            rawget(_G, "ExecuteConsoleCommand"),
            rawget(_G, "RunConsoleCommand")
        }
        for _, fn in ipairs(candidates) do
            if type(fn) == "function" then
                pcall(fn, "t.MaxFPS 120")
                applied = true
                break
            end
        end
    end)

    _G.__FPS120_APPLIED__ = applied
    pcall(function() print("[FPS120] target=120 applied=" .. tostring(applied)) end)
    return applied
end

_ApplyFPS120()
pcall(function()
    local tt = require("common.time_ticker")
    if tt and type(tt.AddTimer) == "function" then
        tt.AddTimer(2, _ApplyFPS120)
        tt.AddTimer(5, _ApplyFPS120)
        tt.AddTimer(10, _ApplyFPS120)
    end
end)

_G.EXPIRY_DATE = "2026-08-25 02:00:00"
_G.EXPIRY_ENABLED = true
_G.EXPIRY_TEST_MODE = false
_G.__MOD_EXPIRED__ = false
_G.__V9_EXPIRY_ACTIVE__ = false
_G.__V9_EXPIRY_LOOP__ = false
_G.__V9_H1_WARNED__ = (_G.__V9_H1_SHOWN_FOR_EXPIRY__ == _G.EXPIRY_DATE)
_G.__SCAM_ALERT_DONE__ = (_G.__SCAM_ALERT_DONE__ == true)

local function _V9ParseExpiryDate(value)
    if type(value) ~= "string" then return nil end

    local y,m,d,hh,mm,ss = value:match(
        "^(%d%d%d%d)%-(%d%d?)%-(%d%d?)%s+(%d%d?):(%d%d):(%d%d)$"
    )

    if not y then return nil end

    return os.time({
        year  = tonumber(y),
        month = tonumber(m),
        day   = tonumber(d),
        hour  = tonumber(hh),
        min   = tonumber(mm),
        sec   = tonumber(ss)
    })
end

local V9_EXPIRY_MESSAGE = "SCRIPT EXPIRED - HUBUNGI ADMIN TELEGRAM @RISKIBAMBELA"

local function _V9ShowExpiryNotification()
    local shown = false

    pcall(function()
        if type(BattleNormalTips) == "function" then
            BattleNormalTips(V9_EXPIRY_MESSAGE, nil, 6)
            shown = true
        end
    end)

    if not shown then
        pcall(function()
            local tips = require("GameLua.Mod.BaseMod.Common.UI.InGameTipsTools")
            if tips and type(tips.BattleNormalTips) == "function" then
                tips.BattleNormalTips(V9_EXPIRY_MESSAGE, nil, 6)
                shown = true
            end
        end)
    end

    if not shown then
        pcall(function()
            local tools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            local main = tools and tools.GetMainControlBaseUI and tools.GetMainControlBaseUI()
            local tb = main and main.TextBlock_Hour
            if tb and type(tb.SetText) == "function" then
                tb:SetText(V9_EXPIRY_MESSAGE)
                local vis = (UEnums and UEnums.ESlateVisibility) or _G.ESlateVisibility
                if vis and type(tb.SetWidgetVisibility) == "function" then
                    tb:SetWidgetVisibility(vis.Visible or vis.SelfHitTestInvisible)
                end
                if type(tb.SetRenderOpacity) == "function" then tb:SetRenderOpacity(1) end
                shown = true
            end
        end)
    end

    pcall(function() print("[V9 EXPIRY] notification="..tostring(shown)) end)
    return shown
end

local function _V9StartExpiryNotificationLoop()
    if _G.__V9_EXPIRY_LOOP__ then return end
    _G.__V9_EXPIRY_LOOP__ = true

    local function tick()
        if _G.__MOD_EXPIRED__ then pcall(_V9ShowExpiryNotification) end
    end

    pcall(function()
        local tt = require("common.time_ticker")
        if tt and type(tt.AddTimerLoop) == "function" then
            _G.__V9_EXPIRY_TIMER__ = tt.AddTimerLoop(4, tick, -1, 1)
            return
        end
        if tt and type(tt.AddTimer) == "function" then
            local function retry()
                tick()
                pcall(tt.AddTimer, 4, retry)
            end
            pcall(tt.AddTimer, 1, retry)
        end
    end)

    pcall(function()
        if type(_G.SetTimer) == "function" then
            local function retry()
                tick()
                pcall(_G.SetTimer, 4, retry)
            end
            pcall(_G.SetTimer, 1, retry)
        end
    end)
end

local function _V9IsExpired()

    if _G.__MOD_EXPIRED__ then
        return true
    end

    if _G.EXPIRY_TEST_MODE == true then
        return true
    end

    if not _G.EXPIRY_ENABLED then
        return false
    end

    local expiry = _V9ParseExpiryDate(_G.EXPIRY_DATE)
    if not expiry then
        pcall(function()
            print("[V10 EXPIRY] INVALID DATE: "..tostring(_G.EXPIRY_DATE))
        end)
        return false
    end

    if os.time() >= expiry then

        _G.EXPIRY_TEST_MODE = true

        pcall(function()
            print("[V10 EXPIRY] EXPIRED -> EXPIRY_TEST_MODE = true")
        end)

        return true
    end

    return false
end

local function _V9RestoreVehicleDefaultsOnExpire()
    -- Restore the currently spawned vehicle to its native/default avatar.
    -- This runs once when the script expires, then all vehicle skin reapply
    -- entry points are blocked by the guards above.
    pcall(function()
        local vehicle = F.getCurrentVehicleForSkin and F.getCurrentVehicleForSkin() or nil
        if not slua.isValid(vehicle) then return end

        local av = F.getVehicleAvatarComp and F.getVehicleAvatarComp(vehicle) or nil
        if not slua.isValid(av) then return end

        local defaultId = 0
        pcall(function()
            defaultId = tonumber(av:GetDefaultAvatarID()) or 0
        end)

        if defaultId <= 0 then
            pcall(function()
                if vehicle.AvatarDefaultCfg and vehicle.AvatarDefaultCfg.TypeSpecificID then
                    defaultId = tonumber(vehicle.AvatarDefaultCfg.TypeSpecificID) or 0
                end
            end)
        end

        if defaultId > 0 then
            pcall(function()
                if av.CanChangeAvatar ~= nil then av.CanChangeAvatar = true end
                if av.ChangeItemAvatar then
                    av:ChangeItemAvatar(defaultId, true)
                elseif av.PreChangeVehicleAvatar then
                    av:PreChangeVehicleAvatar(defaultId)
                end
                if av.PostChangeItemAvatar then av:PostChangeItemAvatar(false) end
            end)

            pcall(function()
                local pc = F.getPC and F.getPC() or nil
                if slua.isValid(pc) then
                    pc.ShowVehicleSkin = defaultId
                    if pc.VehicleAvatarList then
                        local UAvatarUtils = import("AvatarUtils")
                        local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defaultId))
                        if shape and shape >= 0 then
                            pc.VehicleAvatarList:Add(shape, defaultId)
                        end
                    end
                    if pc.ChangeVehicleAvatar then
                        pc:ChangeVehicleAvatar()
                    end
                    if pc.ForceNetUpdate then pc:ForceNetUpdate() end
                end
            end)

            pcall(function()
                if vehicle.ChangeVehicleAvatar then
                    local pc = F.getPC and F.getPC() or nil
                    if slua.isValid(pc) then vehicle:ChangeVehicleAvatar(pc) end
                end
            end)
        end

        pcall(function()
            if vehicle.ForceNetUpdate then vehicle:ForceNetUpdate() end
        end)

        _G.CurrentEquipVehicleID = 0
    end)

    -- Prevent delayed/ticker state from selecting the expired skin again.
    pcall(function()
        local s = rawget(_G, "AddOutfitVehSel")
        if type(s) == "table" then
            s.override = nil
            s.overrideVehicle = nil
            s.byShape = {}
        end
    end)

    _G.__V9_VEHICLE_EXPIRE_CLEANED__ = true
end

local function _V9DisableAllFeatures()
    if _G.__V9_FEATURES_DISABLED__ then return end
    _G.__V9_FEATURES_DISABLED__ = true

    if not _G.__V9_VEHICLE_EXPIRE_CLEANED__ then
        pcall(_V9RestoreVehicleDefaultsOnExpire)
    end

    pcall(function()
        local tt = require("common.time_ticker")
        if _G.weaponAvatarTimerIndex and tt and tt.RemoveTimer then tt.RemoveTimer(_G.weaponAvatarTimerIndex) end
        if _G.TrainingDeadBox and _G.TrainingDeadBox._timerIndex and tt and tt.RemoveTimer then
            tt.RemoveTimer(_G.TrainingDeadBox._timerIndex)
        end
        if _G.__V9_EXPIRY_WATCH_TIMER__ and tt and tt.RemoveTimer then
            tt.RemoveTimer(_G.__V9_EXPIRY_WATCH_TIMER__)
        end
        if _G.__V9_EXPIRY_TIMER__ and tt and tt.RemoveTimer then
            tt.RemoveTimer(_G.__V9_EXPIRY_TIMER__)
        end
    end)

    pcall(function()
        if _G.WAM and _G.WAM.Stop then _G.WAM.Stop() end
        if _G.PhoenixtraSummon and _G.PhoenixtraSummon.Stop then _G.PhoenixtraSummon.Stop() end
        if _G.StopWeaponAnimation then _G.StopWeaponAnimation() end
    end)

    pcall(function()
        local C = _G.X3 and _G.X3.XthrlenConfig
        if type(C) == "table" then
            for k, v in pairs(C) do
                if type(v) == "boolean" then C[k] = false end
            end
        end
    end)

    local names = {
        "GameAvatarHandlerweapons", "GameAvatarHandlerkillcounter",
        "GameAvatarHandlerBagPack", "GameAvatarHandlerplayers", "GameCameraView", "HandlePetLogic",
        "ApplyPetSkinInGame", "GameAvatarHandlerplayers"
    }
    for _, name in ipairs(names) do
        _G[name] = function() return false end
    end

    pcall(function()
        local UM = rawget(_G, "UIManager")
        if UM and UM.UI_Config and UM.UI_Config.setting_main and UM.CloseUI then
            UM.CloseUI(UM.UI_Config.setting_main)
        end
    end)
end

local function _V9HideExpiredMenu()
    if not _G.__MOD_EXPIRED__ then return end
    pcall(function()
        local UM = rawget(_G, "UIManager")
        if not UM then return end
        if UM.UI_Config and UM.UI_Config.setting_main and UM.CloseUI then
            UM.CloseUI(UM.UI_Config.setting_main)
        end
        if UM.UI_Config_InGame and UM.UI_Config_InGame.SettingMain and UM.CloseUI then
            UM.CloseUI(UM.UI_Config_InGame.SettingMain)
        end
    end)
end

local function _V9ExpireNow()
    _G.__MOD_EXPIRED__ = true
    _G.__V9_EXPIRY_ACTIVE__ = true

    _G.EXPIRY_TEST_MODE = true
    _V9DisableAllFeatures()
    _V9HideExpiredMenu()

    _V9StartExpiryNotificationLoop()
end

local function _V9ShowH1ExactBanner()
    if _G.__V9_H1_EXACT_ACTIVE__ then
        return true
    end

    local ok, result = pcall(function()
        local hud = require("game_frontend_hud")
        local WLL = import("WidgetLayoutLibrary")

        if not hud or not hud.AddToContainer then
            return false
        end

        if not WLL or not WLL.SlotAsCanvasSlot then
            return false
        end

        local widgets = {}
        local Z = 11500

        local CX = 0
        local CY = -95

        local function valid(w)
            return w and slua.isValid(w)
        end

        local function addWidget(w, x, y, width, height, color)
            if not valid(w) then
                return false
            end

            hud.AddToContainer(UIContainers.Top, w, Z)
            Z = Z + 1

            local slot = WLL.SlotAsCanvasSlot(w)
            if slot then
                slot:SetAnchors({
                    Minimum = {X = 0.5, Y = 0.5},
                    Maximum = {X = 0.5, Y = 0.5}
                })
                slot:SetAlignment({X = 0.5, Y = 0.5})
                slot:SetPosition({X = x, Y = y})
                slot:SetSize({X = width, Y = height})
            end

            if color and w.SetColorAndOpacity then
                pcall(function()
                    w:SetColorAndOpacity(color)
                end)
            end

            if w.SetWidgetVisibility then
                pcall(function()
                    w:SetWidgetVisibility(
                        UEnums.ESlateVisibility.SelfHitTestInvisible
                    )
                end)
            end

            widgets[#widgets + 1] = w
            return true
        end

        local function newWidget(x, y, width, height, color)
            local w = slua.loadUI(
                "/Game/UMG/UI_BP/Common/BaseComponent/CommonBaseComponent_TextButton_UIBP.CommonBaseComponent_TextButton_UIBP"
            )

            if not valid(w) then
                return nil
            end

            if not addWidget(w, x, y, width, height, color) then
                return nil
            end

            return w
        end

        local function setText(w)
            if not valid(w) then
                return false
            end

            local txt = w.RichText_Content
            if not txt then
                return false
            end

            local done = false

            pcall(function()
                txt:SetText("SCRIP ANDA BESOK SUDAH BERAKHIR")

                local f = txt.Font
                if f then
                    f.Size = 17
                    f.TypefaceFontName = "Bold"
                    txt:SetFont(f)
                end

                txt:SetColorAndOpacity(
                    FSlateColor(FLinearColor(0.03, 0.03, 0.03, 1.0))
                )

                if txt.SetRenderOpacity then
                    txt:SetRenderOpacity(1.0)
                end

                if txt.SetWidgetVisibility then
                    txt:SetWidgetVisibility(
                        UEnums.ESlateVisibility.Visible
                    )
                end

                if txt.SetVisibility then
                    txt:SetVisibility(
                        UEnums.ESlateVisibility.Visible
                    )
                end

                if txt.SetDefaultColorAndOpacity then
                    txt:SetDefaultColorAndOpacity(
                        FSlateColor(FLinearColor(0.03, 0.03, 0.03, 1.0))
                    )
                end

                done = true
            end)

            return done
        end

        local BW = 280
        local BH = 42

        local bg = newWidget(
            CX, CY, BW, BH,
            FLinearColor(0.025, 0.030, 0.035, 0.94)
        )

        local txtWidget = newWidget(
            CX, CY, BW - 10, BH - 6,
            FLinearColor(1.0, 1.0, 1.0, 1.0)
        )

        pcall(function()
            for _, name in ipairs({
                "Button",
                "Background",
                "Image_Background",
                "Image_Bg",
                "Border"
            }) do
                local w = txtWidget[name]
                if w then
                    if w.SetColorAndOpacity then
                        w:SetColorAndOpacity(
                            FLinearColor(1.0, 1.0, 1.0, 0.0)
                        )
                    end
                    if w.SetBrushColor then
                        w:SetBrushColor(
                            FLinearColor(1.0, 1.0, 1.0, 0.0)
                        )
                    end
                end
            end
        end)

        local yellow = FLinearColor(0.98, 0.70, 0.08, 1.0)

        local top = newWidget(CX, CY - 20, BW, 2, yellow)
        local bottom = newWidget(CX, CY + 20, BW, 2, yellow)
        local left = newWidget(CX - 139, CY, 2, BH, yellow)
        local right = newWidget(CX + 139, CY, 2, BH, yellow)

        local corner = FLinearColor(0.98, 0.70, 0.08, 1.0)

        newWidget(CX - 133, CY - 16, 10, 2, corner)
        newWidget(CX - 133, CY + 16, 10, 2, corner)
        newWidget(CX + 133, CY - 16, 10, 2, corner)
        newWidget(CX + 133, CY + 16, 10, 2, corner)

        local arrow = newWidget(
            CX, CY + 28, 12, 8,
            yellow
        )

        if not bg or not txtWidget then
            return false
        end

        local shown = setText(txtWidget)

        pcall(function()
            local tt = require("common.time_ticker")
            if tt and type(tt.AddTimer) == "function" then
                tt.AddTimer(0.1, function()
                    pcall(function() setText(txtWidget) end)
                end)
                tt.AddTimer(0.3, function()
                    pcall(function() setText(txtWidget) end)
                end)
                tt.AddTimer(0.7, function()
                    pcall(function() setText(txtWidget) end)
                end)
                tt.AddTimer(1.5, function()
                    pcall(function() setText(txtWidget) end)
                end)
                tt.AddTimer(2.5, function()
                    pcall(function() setText(txtWidget) end)
                end)
            end
        end)

        _G.__V9_H1_EXACT_WIDGETS__ = widgets
        _G.__V9_H1_EXACT_ACTIVE__ = true

        local started = os.clock()
        local duration = 15.0

        local function destroy()
            pcall(function()
                local list = _G.__V9_H1_EXACT_WIDGETS__
                if list then
                    for _, w in ipairs(list) do
                        if valid(w) then
                            w:RemoveFromParent()
                        end
                    end
                end
            end)

            _G.__V9_H1_EXACT_WIDGETS__ = nil
            _G.__V9_H1_EXACT_ACTIVE__ = false
        end

        local function update()
            if not _G.__V9_H1_EXACT_ACTIVE__ then
                return false
            end

            if os.clock() - started >= duration then
                destroy()
                return false
            end

            return true
        end

        pcall(function()
            local tt = require("common.time_ticker")
            if tt and type(tt.AddTimerLoop) == "function" then
                _G.__V9_H1_EXACT_TIMER__ =
                    tt.AddTimerLoop(0.25, update, -1, 1)
            end
        end)

        print(
            "[RISKI H1] Compact banner above-head tampil: "
            .. tostring(shown)
        )

        return true
    end)

    if not ok or result ~= true then
        _G.__V9_H1_EXACT_ACTIVE__ = false
        _G.__V9_H1_EXACT_WIDGETS__ = nil
        return false
    end

    _G.__V9_H1_WARNED__ = true
    _G.__V9_H1_SHOWN_FOR_EXPIRY__ = _G.EXPIRY_DATE

    return true
end

local function _V9StartExpiryWatcher()
    if _G.__V9_EXPIRY_WATCHER__ then return end
    _G.__V9_EXPIRY_WATCHER__ = true
    local function tick()
        if not _G.__MOD_EXPIRED__ then

            if _G.__SCAM_ALERT_DONE__ == true and not _G.__V9_H1_WARNED__ and not _G.__V9_H1_EXACT_ACTIVE__ and _G.EXPIRY_ENABLED == true and _G.EXPIRY_TEST_MODE ~= true then
                local e = _V9ParseExpiryDate(_G.EXPIRY_DATE)

                if e then
                    local left = e - os.time()

                    if left > 0 and left <= 86400 then
                        local shown = false

                        _G.__V9_H1_WARNED__ = true
                        _G.__V9_H1_SHOWN_FOR_EXPIRY__ = _G.EXPIRY_DATE

                        pcall(function()
                            shown = _V9ShowH1ExactBanner() == true
                        end)

                        if not shown then
                            _G.__V9_H1_WARNED__ = false
                            _G.__V9_H1_SHOWN_FOR_EXPIRY__ = nil
                        end
                    end
                end
            end

            if _V9IsExpired() then _V9ExpireNow() end
        end
        if _G.__MOD_EXPIRED__ then _V9DisableAllFeatures(); _V9HideExpiredMenu() end
    end
    pcall(function()
        local tt = require("common.time_ticker")
        if tt and type(tt.AddTimerLoop) == "function" then
            _G.__V9_EXPIRY_WATCH_TIMER__ = tt.AddTimerLoop(5, tick, -1, 1)
            return
        end
        if tt and type(tt.AddTimer) == "function" then
            local function retry()
                tick()
                if not _G.__MOD_EXPIRED__ then pcall(tt.AddTimer, 1, retry) end
            end
            pcall(tt.AddTimer, 1, retry)
        end
    end)
    pcall(function()
        if type(_G.SetTimer) == "function" then
            local function retry()
                tick()
                if not _G.__MOD_EXPIRED__ then pcall(_G.SetTimer, 1, retry) end
            end
            pcall(_G.SetTimer, 1, retry)
        end
    end)
end

if _V9IsExpired() then
    _V9ExpireNow()
    pcall(_V9ShowExpiryNotification)
else
    _V9StartExpiryWatcher()
end

local function _CheckGlobalExpiry()
    if _V9IsExpired() then
        _V9ExpireNow()
        _V9DisableAllFeatures()
        _V9HideExpiredMenu()
        pcall(_V9ShowExpiryNotification)
        return true
    end
    return false
end

