function _G.GameCameraView(forceApply)
    if _G.__MOD_EXPIRED__ then return false end

    if not _G.ConfigFOVEnable then
        local restored = false

        pcall(function()
            if slua.isValid(_SavedFOVCharacter) then
                local CameraComponentFPP = _SavedFOVCharacter:GetFPPCamera()
                if slua.isValid(CameraComponentFPP) and _SavedFOVFPP then
                    CameraComponentFPP:SetFieldOfView(_SavedFOVFPP)
                    restored = true
                end

                local CameraComponentThird = _SavedFOVCharacter:GetThirdPersonCamera()
                if slua.isValid(CameraComponentThird) and _SavedFOVThird then
                    CameraComponentThird:SetFieldOfView(_SavedFOVThird)
                    restored = true
                end
            end
        end)

        _LastAppliedFOV = nil
        _LastFOVCharacter = nil
        _SavedFOVCharacter = nil
        _SavedFOVFPP = nil
        _SavedFOVThird = nil
        return restored
    end

    local desiredFOV = tonumber(_G.ConfigFOV) or 110
    if desiredFOV < 90 then desiredFOV = 90 end
    if desiredFOV > 120 then desiredFOV = 120 end

    local ok, GameplayData = pcall(_require, "GameLua.GameCore.Data.GameplayData")
    if not ok or not GameplayData then
        _LastAppliedFOV = nil
        _LastFOVCharacter = nil
        return false
    end

    local okChar, uCharacter = pcall(GameplayData.GetPlayerCharacter)
    if not okChar or not slua.isValid(uCharacter) then
        _LastAppliedFOV = nil
        _LastFOVCharacter = nil
        return false
    end

    if _SavedFOVCharacter ~= uCharacter then
        _SavedFOVCharacter = uCharacter
        _SavedFOVFPP = nil
        _SavedFOVThird = nil

        pcall(function()
            local CameraComponentFPP = uCharacter:GetFPPCamera()
            if slua.isValid(CameraComponentFPP) then
                local okFOV, currentFOV = pcall(function()
                    return CameraComponentFPP:GetFieldOfView()
                end)
                if okFOV and tonumber(currentFOV) then
                    _SavedFOVFPP = tonumber(currentFOV)
                end
            end
        end)

        pcall(function()
            local CameraComponentThird = uCharacter:GetThirdPersonCamera()
            if slua.isValid(CameraComponentThird) then
                local okFOV, currentFOV = pcall(function()
                    return CameraComponentThird:GetFieldOfView()
                end)
                if okFOV and tonumber(currentFOV) then
                    _SavedFOVThird = tonumber(currentFOV)
                end
            end
        end)

        if not _SavedFOVFPP then _SavedFOVFPP = 90 end
        if not _SavedFOVThird then _SavedFOVThird = 90 end
    end

    local applied = false

    pcall(function()
        local CameraComponentFPP = uCharacter:GetFPPCamera()
        if slua.isValid(CameraComponentFPP) then
            CameraComponentFPP:SetFieldOfView(desiredFOV)
            applied = true
        end
    end)

    pcall(function()
        local CameraComponentThird = uCharacter:GetThirdPersonCamera()
        if slua.isValid(CameraComponentThird) then
            CameraComponentThird:SetFieldOfView(desiredFOV)
            applied = true
        end
    end)

    if applied then
        _LastAppliedFOV = desiredFOV
        _LastFOVCharacter = uCharacter
    else
        _LastAppliedFOV = nil
        _LastFOVCharacter = nil
    end

    return applied
end

function _G.FakeBanSetup()
    pcall(function()
        local ModuleManager = require("client.module_framework.ModuleManager")
        if not ModuleManager then return end

        local logic_profile = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.logic_profile)
        if logic_profile then
            logic_profile.IsPlayerBanned = function(uid) return true end
            logic_profile.IsPlayerBannedOver30day = function(uid) return true end
            logic_profile.IsPlayerChatBanned = function(uid) return true end
        end

        local ui = require("client.slua_ui_framework.manager").GetUI(
            require("client.slua_ui_framework.manager").UI_Config.Lobby_Main_UIBP
        )
        if ui and ui.Common_Avatar_BP then
            ui.Common_Avatar_BP:SetPlayerBanned(true)
        end

        require("client.slua.event.EventSystem"):postEvent(2, 10001)
    end)
end

