            Mask      = "_G.MaskSkin",
            Jacket    = "_G.SuitSkin",
            Trouser   = "_G.PantSkin",
            Shoe      = "_G.ShoeSkin",
            Glasses   = "_G.FaceSkin",
            Gloves    = "_G.GlovesSkin",
            Parachute = "_G.ParachuteSkin",
            Glider    = "_G.GliderSkin",
            Aircraft  = "_G.AircraftSkin",
