    local function GetHelmetSkinByLevel()
        return GetHelmetSkinFromNMSL()
    end

    local function GetBackpackSkinByLevel()
        return GetBackpackSkinFromNMSL()
    end

    local E = UEnums.EBackpackClothArmorType

    local SLOT_MAP = {
        Cap       = E.Cap,
        Mask      = E.Mask,
        Jacket    = E.Jacket,
