        Package   = E.Package,
        Guns      = E.Guns,
        Glider    = E.Glider,
    }

    local function GetSkinIdFromNMSL(clothType)
        if clothType == E.Helmet then
            return GetHelmetSkinByLevel()
        end
        if clothType == E.Package then
            return GetBackpackSkinByLevel()
        end

        local nameMap = {
            [E.Cap]       = "HatSkin",
            [E.Mask]      = "MaskSkin",
